#include "Aevrynd/Scene3D.h"
#include <chrono>
#include <cmath>
#include <iostream>
#include <memory>

using namespace Aevrynd;

int main(){
    constexpr std::uint32_t cells=128,stride=cells+1;auto mesh=std::make_shared<Mesh3D>();mesh->vertices.reserve(std::size_t{stride}*stride);mesh->indices.reserve(std::size_t{cells}*cells*6);for(std::uint32_t z=0;z<=cells;++z)for(std::uint32_t x=0;x<=cells;++x)mesh->vertices.push_back({float(x),.2f*std::sin(float(x+z)*.1f),float(z),PackNormalSnorm8({0,1,0}),0xffffffffu});for(std::uint32_t z=0;z<cells;++z)for(std::uint32_t x=0;x<cells;++x){const std::uint32_t a=z*stride+x,b=a+1,c=a+stride,d=c+1;mesh->indices.insert(mesh->indices.end(),{a,c,b,b,c,d});}
    const std::size_t triangleCount=mesh->indices.size()/3;MeshResource3D resource{MeshHandle3D{1},mesh->Bounds(),mesh->vertices.size(),mesh->indices.size(),mesh};Scene3D scene;for(std::size_t instance=0;instance<8;++instance)scene.Mesh(resource,{{float(instance)*160.f,0,0},{},{1,1,1}});
    constexpr std::size_t queryCount=512;std::size_t candidates{},nodes{};std::uint64_t builds{};const auto start=std::chrono::steady_clock::now();for(std::size_t query=0;query<queryCount;++query){const std::size_t instance=query%8;const float x=float(instance)*160.f+float((query*37)%cells)+.25f,z=float((query*53)%cells)+.25f;SceneQueryStats3D stats{};if(!scene.Raycast({{x,20,z},{0,-1,0}},50,&stats)){std::cerr<<"Benchmark raycast failed at query "<<query<<'\n';return 1;}candidates+=stats.meshTriangleCandidates;nodes+=stats.meshBvhNodesTested;builds+=stats.meshBvhBuilds;}const auto elapsed=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start).count();const std::size_t averageCandidates=candidates/queryCount;if(builds!=1){std::cerr<<"Unexpected mesh BVH build count\n";return 2;}if(averageCandidates>=triangleCount/50){std::cerr<<"Mesh BVH candidate reduction failed\n";return 3;}std::cout<<"triangles="<<triangleCount<<" queries="<<queryCount<<" averageCandidates="<<averageCandidates<<" averageNodes="<<nodes/queryCount<<" elapsedUs="<<elapsed<<"\n";
}
